import fs from 'node:fs'
import path from 'node:path'

const P='call-wild', worldId=`${P}-world`, timelineId=`${P}-timeline`, now=1788393600000, base={worldId,createdAt:now,updatedAt:now}
const id=(k,s)=>`${P}-${k}-${s}`, I=s=>id('image',s), C=s=>id('character',s), L=s=>id('location',s), M=s=>id('map',s), Ch=n=>id('chapter',String(n).padStart(2,'0')), E=s=>id('event',s), Item=s=>id('item',s), T=s=>id('thread',s), O=s=>id('motif',s), F=s=>id('faction',s), K=s=>id('fact',s)
const assetRoot='public/library/the-call-of-the-wild', publicPath='library/the-call-of-the-wild'
fs.mkdirSync(`${assetRoot}/maps`,{recursive:true});fs.mkdirSync(`${assetRoot}/art`,{recursive:true})
const esc=s=>s.replaceAll('&','&amp;')
function mapSvg(file,title,subtitle,points,lines=[]){const dots=points.map(([name,x,y])=>`<g><circle cx="${x}" cy="${y}" r="10" fill="#e4bd71" stroke="#201b18" stroke-width="4"/><text x="${x+15}" y="${y-10}" fill="#f5ead7" font-size="18" font-family="Georgia">${esc(name)}</text></g>`).join('');const paths=lines.map(d=>`<path d="${d}" fill="none" stroke="#b68a52" stroke-width="6" stroke-dasharray="12 9"/>`).join('');fs.writeFileSync(`${assetRoot}/maps/${file}.svg`,`<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="900" viewBox="0 0 1400 900"><rect width="1400" height="900" fill="#23343d"/><path d="M0 620 Q220 500 410 610 T800 540 T1400 590 V900 H0Z" fill="#e9e6db"/><path d="M0 710 Q300 600 590 720 T1100 650 T1400 700" fill="none" stroke="#9fc3d1" stroke-width="32"/><g opacity=".28" stroke="#fff" stroke-width="2">${Array.from({length:18},(_,i)=>`<path d="M${i*90} 0 L${i*65+150} 900"/>`).join('')}</g>${paths}${dots}<text x="55" y="70" fill="#f4dfb2" font-size="38" font-family="Georgia" font-weight="bold">${esc(title)}</text><text x="57" y="105" fill="#c7d6da" font-size="18" font-family="Georgia">${esc(subtitle)}</text><path d="M1280 105 l25 -55 l25 55 h-18 v55 h-14 v-55z" fill="#e4bd71"/><text x="1300" y="185" text-anchor="middle" fill="#f5ead7" font-size="18">N</text></svg>`)}
function artSvg(file,title,kind,accent='#b47745'){const shape=kind==='dog'?`<path d="M300 560 Q330 330 520 300 Q650 160 790 300 Q950 330 1060 540 L920 550 Q850 700 690 690 Q500 720 420 570Z"/><path d="M520 310 L430 170 L620 270 M790 300 L900 160 L850 350"/>`:kind==='person'?`<circle cx="700" cy="250" r="115"/><path d="M430 760 Q470 390 700 390 Q930 390 970 760Z"/>`:`<rect x="420" y="230" width="560" height="470" rx="35"/><path d="M500 330 H900 M500 430 H850 M500 530 H920"/>`;fs.writeFileSync(`${assetRoot}/art/${file}.svg`,`<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="900"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#15252d"/><stop offset="1" stop-color="#394f55"/></linearGradient></defs><rect width="1400" height="900" fill="url(#g)"/><circle cx="1160" cy="170" r="95" fill="#e8d6aa" opacity=".8"/><g fill="${accent}" stroke="#ead9b4" stroke-width="8">${shape}</g><path d="M0 760 Q250 650 460 750 T900 720 T1400 760 V900 H0Z" fill="#e7e5dd"/><text x="55" y="75" fill="#f3dfb1" font-size="38" font-family="Georgia" font-weight="bold">${esc(title)}</text></svg>`)}

mapSvg('pacific','Pacific Coast to the Klondike','Editorial route on a period-inspired geographic chart',[['Santa Clara Valley',220,690],['Seattle',305,460],['Dyea',660,300],['Dawson',1040,250],['East Fork',1190,430]],['M220 690 Q270 560 305 460 Q450 360 660 300 Q850 230 1040 250 Q1130 300 1190 430'])
mapSvg('northland','The Northland Trail','Editorial reconstruction; north is up',[['Dyea Beach',170,680],['Chilkoot Pass',300,510],['Lake Bennett',450,450],['Dawson',820,310],['Thirty Mile River',600,390],['Skaguay',160,590],['East Fork',1100,500],['Wolf Valley',1210,350]],['M170 680 L300 510 L450 450 L600 390 L820 310','M160 590 L300 510','M820 310 Q990 390 1100 500 L1210 350'])
mapSvg('camp','Northland Sled Camp','Interpretive camp plan; north is up',[['Fire',700,420],['Dogs’ Line',470,560],['Sled',880,570],['Tent',700,240],['Forest Edge',1110,290],['Trail',1160,650]],['M180 700 Q700 650 1220 700'])

const mapRows=[['pacific',null,'Pacific Coast and the Klondike','A navigational overview of Buck’s forced route from California through Puget Sound to the Yukon and his final movement east of Dawson.'],['northland','pacific','The Northland Trail','An editorial trail map connecting Dyea, the Chilkoot crossing, Lake Bennett, the Yukon river route, Dawson, Skaguay, and the East Fork country.'],['camp','northland','A Northland Sled Camp','An interpretive plan of the repeated camp arrangement: tent and fire at the centre, dogs secured near the sled, trail beyond the timber.']]
const maps=mapRows.map(([s,p,name,description])=>({...base,id:M(s),parentMapId:p?M(p):null,name,description,imageId:I(`map-${s}`),imageWidth:1400,imageHeight:900,scalePixelsPerUnit:null,scaleUnit:null,levelGroupId:null,levelIndex:0,levelLabel:''}))
const locRows=[
 ['santa','pacific','Judge Miller’s Estate','A broad Santa Clara Valley property with lawns, orchards, veranda, and bathing tank where Buck lives as a trusted household dog.','',220,690,'home'],['seattle','pacific','Seattle Depot and Saloon','Rail yards and a back-room yard mark the transfer from domestic theft into the northern dog trade.','',305,460,'building'],['north-gate','pacific','Alaska and the Yukon','The northern field of snow trails, river ice, mining settlements, and forest beyond settled authority.','northland',760,285,'region'],['east-overview','pacific','East Fork Country','Remote tributaries east of Dawson hold Thornton’s camp, the lost mine, and the valley where Buck joins the wolves.','',1190,430,'region'],
 ['dyea','northland','Dyea Beach','A tide-washed landing beneath steep passes where dogs, freight, and stampeders enter the winter trail.','',170,680,'landmark'],['chilkoot','northland','Chilkoot Pass','A steep snowbound ascent where harness teams haul loads over the coastal mountains.','',300,510,'mountain'],['bennett','northland','Lake Bennett','The frozen lake and camp serve as a staging place before the long mail run down the Yukon system.','',450,450,'water'],['thirty-mile','northland','Thirty Mile River','Fast water hidden by uncertain ice makes this reach especially dangerous for men, dogs, and sled.','',600,390,'water'],['dawson','northland','Dawson City','The gold-rush settlement receives official mail, exhausted teams, and men whose fortunes depend on the trail.','',820,310,'town'],['skaguay','northland','Skaguay','The coastal supply town where a worn mail team is sold to inexperienced stampeders.','',160,590,'town'],['east-fork','northland','East Fork Camp','Thornton’s seasonal camp lies away from the main route, close to timber, river, and the search for a legendary mine.','camp',1100,500,'camp'],['wolf-valley','northland','The Wolf Valley','A long, secluded valley of stream, forest, game trails, and an old human trace, beyond the last camp.','',1210,350,'forest'],
 ['fire','camp','Camp Fire','The working centre for food, warmth, judgment, and companionship after a day on the trail.','',700,420,'campfire'],['dog-line','camp','Dogs’ Sleeping Line','Snow hollows near the sled give each dog a defensible sleeping place in severe cold.','',470,560,'custom'],['sled','camp','Freight Sled','Harness, traces, and packed cargo organize the team’s daily labour and hierarchy.','',880,570,'custom'],['tent','camp','Canvas Tent','A compact human shelter whose occupants and discipline determine whether a camp survives.','',700,240,'custom'],['forest','camp','Forest Edge','Spruce and pine begin close to camp, holding game, danger, and the sounds that awaken Buck’s older instincts.','',1110,290,'forest'],['trail','camp','Frozen Trail','Packed snow leaves camp toward the next river bend, pass, or settlement.','',1160,650,'road']]
const locations=locRows.map(([s,m,name,description,linked,x,displayY,iconType])=>({...base,id:L(s),mapLayerId:M(m),linkedMapLayerId:linked?M(linked):null,name,description,x,y:900-displayY,imageId:I(`location-${s}`),iconType,tags:[],factionId:null}))

const charRows=[
 ['buck','Buck',[],'A powerful St Bernard–Scotch shepherd cross taken from a California estate, tested by sled discipline, and drawn toward life beyond human camps.','#9c7048','dog'],['manuel','Manuel',[],'A gardener’s helper whose gambling debts lead him to sell Buck to dog traders.','#806b58','person'],['red-sweater','The Man in the Red Sweater',[],'A dog breaker in Seattle who teaches captured animals the absolute force of the club.','#934f42','person'],['perrault','Perrault',[],'A Canadian government courier who buys Buck and values speed, endurance, and practical dogcraft.','#526f7d','person'],['francois','François',[],'Perrault’s driver, skilled at harness work and fair within the hard law of the trail.','#617467','person'],['spitz','Spitz',[],'The experienced white lead dog whose discipline and cruelty make him Buck’s chief rival.','#d5d2c7','dog'],['curly','Curly',[],'A friendly Newfoundland purchased with Buck whose fate teaches the danger of falling among northern dogs.','#795c4c','dog'],['dave','Dave',[],'A reserved wheel dog who finds dignity in exact sled work even when mortal illness overtakes him.','#64666a','dog'],['sol-leks','Sol-leks',[],'A one-eyed veteran sled dog who avoids provocation and works with severe concentration.','#8c795d','dog'],['scotch-halfbreed','The Scotch Half-Breed',[],'A mail driver who pushes the team through heavy official runs while preserving a competent routine.','#725e50','person'],['hal','Hal',[],'An inexperienced stampeder who mistakes weapons, punishment, and overloaded gear for authority.','#7c5744','person'],['charles','Charles',[],'Hal’s older companion, weakened by travel and unable to correct the party’s destructive decisions.','#6e665c','person'],['mercedes','Mercedes',[],'Charles’s wife and Hal’s sister, attached to comforts the trail cannot carry and distressed by the team’s suffering.','#8d6c6c','person'],['thornton','John Thornton',[],'A seasoned outdoorsman whose rescue gives Buck patient affection without suppressing his strength.','#596f68','person'],['skeet','Skeet',[],'Thornton’s gentle Irish setter, who cleans Buck’s wounds and accepts him into the camp.','#9a6955','dog'],['nig','Nig',[],'Thornton’s large, good-natured dog, a calm companion in work and camp.','#34383a','dog'],['hans','Hans',[],'Thornton’s partner in river travel and the search east of Dawson.','#667b76','person'],['pete','Pete',[],'Thornton’s second partner, steady in camp and on the remote mining journey.','#7b6c52','person'],['black-burton','Black Burton',[],'A violent saloon patron whose attack on Thornton brings Buck into a public fight.','#4f4744','person'],['yeehat-chief','Yeehat War Leader',[],'A leader among the raiders who attack Thornton’s remote camp; the novel does not provide his name.','#765f4d','person'],['timber-wolf','The Timber Wolf',[],'A lean wild wolf whose cautious play becomes Buck’s first sustained bond with a pack.','#7d8586','dog']]
const characters=charRows.map(([s,name,aliases,description,color,kind])=>({...base,id:C(s),name,aliases,description,portraitImageId:I(`character-${s}`),color,tags:[kind],isAlive:!['curly','spitz','dave','thornton','hans','pete','black-burton'].includes(s),birthDate:null}))
const itemRows=[['club','The Club','The dog breaker’s blunt instrument establishes a rule Buck cannot defeat directly.','weapon'],['sled','Mail Sled','A freight and mail sled binds the team into ordered labour across ice and snow.','transport'],['traces','Harness and Traces','Leather gear assigns each dog a place and transmits the team’s strength to the load.','equipment'],['moccasins','Buck’s Moccasins','François makes leather foot coverings when Buck’s paws soften on the punishing trail.','clothing'],['revolver','Hal’s Revolver','Hal displays the pistol as authority, though it cannot supply judgment or food.','weapon'],['club-hal','Hal’s Club','Repeated beating turns an exhausted team’s suffering into open cruelty.','weapon'],['thousand','Thornton’s Wager Stake','Money wagered on Buck’s ability to start and pull a thousand-pound load.','currency'],['gold','Gold from the Lost Mine','Coarse yellow metal gathered at the remote mine rewards Thornton’s long search.','treasure'],['antlers','Great Moose Antlers','The antlers mark the immense bull Buck isolates and hunts over several days.','trophy']]
const items=itemRows.map(([s,name,description,type])=>({...base,id:Item(s),name,description,type,imageId:I(`item-${s}`),tags:[]}))
for(const [s,name,,, ,kind] of charRows)artSvg(`character-${s}`,name,kind,s==='buck'?'#9b6a3f':undefined)
for(const [s,name,,type] of itemRows)artSvg(`item-${s}`,name,'item',type==='weapon'?'#8b4f43':'#ac854d')
for(const [s,,name] of locRows)artSvg(`location-${s}`,name,'item','#587c79')
artSvg('world','The Call of the Wild','dog','#9b6a3f')
const blobs=[{...base,id:I('world'),mimeType:'image/svg+xml',url:`${publicPath}/art/world.svg`},...maps.map(m=>({...base,id:m.imageId,mimeType:'image/svg+xml',url:`${publicPath}/maps/${m.id.replace(`${P}-map-`,'')}.svg` })),...characters.map(c=>({...base,id:c.portraitImageId,mimeType:'image/svg+xml',url:`${publicPath}/art/${c.portraitImageId.replace(`${P}-image-`,'')}.svg`})),...items.map(x=>({...base,id:x.imageId,mimeType:'image/svg+xml',url:`${publicPath}/art/${x.imageId.replace(`${P}-image-`,'')}.svg`})),...locations.map(x=>({...base,id:x.imageId,mimeType:'image/svg+xml',url:`${publicPath}/art/${x.imageId.replace(`${P}-image-`,'')}.svg`}))]

const chapterRows=[['Into the Primitive','Buck is stolen from his California home, transported north, and initiated into the violence and cold of the dog trade.'],['The Law of Club and Fang','Buck learns camp survival, harness work, and the social law enforced by human clubs and canine teeth.'],['The Dominant Primordial Beast','Buck challenges Spitz through daily resistance and finally wins leadership in a decisive fight.'],['Who Has Won to Mastership','Buck forces recognition as lead dog and drives Perrault and François’s team to record speed.'],['The Toil of Trace and Trail','Mail service exhausts the team; Dave’s fatal decline and sale to unprepared owners expose the cost of relentless work.'],['For the Love of a Man','Thornton rescues Buck, earns his devotion, and sees that devotion tested in rescue, combat, and a famous wager.'],['The Sounding of the Call','Beyond Dawson, Buck ranges farther from camp until loss severs his human bond and he joins the wild pack.']]
const chapters=chapterRows.map(([title,synopsis],i)=>({...base,id:Ch(i+1),timelineId,number:i+1,title,synopsis,notes:'',wordGoal:null}))
const beats=[
[1,'estate','Life at Judge Miller’s','Buck rules the estate’s outdoor life, confident in the permanence of household, grounds, and human regard.','santa',{buck:'Patrols the lawns and orchard as the acknowledged master of the estate’s dogs.'},1,1],
[1,'stolen','Manuel Sells Buck','Manuel secretly ropes Buck and transfers him at a railway flag stop to pay gambling debts.','santa',{buck:'Fights the choking rope in disbelief as a familiar servant delivers him to strangers.',manuel:'Completes the covert sale while keeping Buck away from Judge Miller’s household.'},4,1.6],
[1,'crate','Crated North','Handlers move Buck by rail and ship without food or water, turning resistance into exhausted watchfulness.','seattle',{buck:'Guards his remaining strength inside the crate and learns to distrust every approaching hand.'},4,4],
[1,'club','The Red Sweater’s Lesson','Released into a fenced yard, Buck attacks repeatedly until the man’s club establishes an unequal law.','seattle',{buck:'Stops charging only after repeated blows prove that courage cannot overcome the club.', 'red-sweater':'Controls the yard through measured violence and waits for Buck to acknowledge defeat.'},5,5],
[1,'bought','Perrault Buys the Team','Perrault selects Buck and Curly for government service and takes them north with François.','seattle',{buck:'Studies the capable new owners without offering the trust he once gave freely.',perrault:'Chooses Buck for strength and intelligence after testing the dog market.',francois:'Receives responsibility for feeding, handling, and later harnessing the purchases.',curly:'Greets Buck openly while sharing the uncertain transfer to the northern ship.'},2,6],
[2,'snow','First Snow at Dyea','Buck steps onto snow for the first time as the dogs and equipment are landed at Dyea.','dyea',{buck:'Tests the strange cold powder with nose and tongue while onlookers laugh.',perrault:'Moves the government outfit efficiently off the beach toward the trail.',francois:'Keeps the newly landed dogs together amid freight and confusion.',curly:'Stays close to Buck in the unfamiliar coastal camp.',spitz:'Observes the newcomers with the confidence of an experienced northern dog.'},2,10],
[2,'curly','Curly Falls','Curly approaches a husky, is slashed down, and is killed by the surrounding pack before help can reach her.','dog-line',{buck:'Watches without joining and fixes the lesson never to fall before a hostile pack.',curly:'Dies beneath the converging dogs after her friendly approach meets a sudden attack.',spitz:'Laughs from the edge of the circle, earning Buck’s lasting hatred.',francois:'Drives the pack away too late to save Curly.'},5,10.2],
[2,'harness','Buck Learns the Traces','François places Buck between Dave and Sol-leks, and the veteran dogs correct his first mistakes.','sled',{buck:'Leans into the traces, rapidly connecting commands, turns, and teamwork.',francois:'Uses voice, whip, and placement to teach without wasting the new dog.',dave:'Nips Buck’s hindquarters whenever slack work disrupts the wheel position.','sol-leks':'Shoulders Buck back into line when inexperience tangles the traces.'},3,11],
[2,'burrow','A Bed under Snow','Shut out from the tent, Buck copies the team and sleeps in a hollow beneath the snow.','dog-line',{buck:'Curls beneath the insulating snow after following the scent of buried dogs.',spitz:'Occupies his own hollow and yields no privileged shelter to the newcomer.',dave:'Sleeps apart after the day’s labour, uninterested in camp quarrels.','sol-leks':'Protects his blind side while settling into the dogs’ line.'},2,11.8],
[2,'food','Theft and Adaptation','Hunger teaches Buck to eat rapidly and steal food without being detected.','fire',{buck:'Snatches an extra ration and conceals the act, adapting intelligence to scarcity.',francois:'Counts portions carefully but misses Buck’s first successful theft.',perrault:'Prepares the next stage while relying on François to keep the team fit.'},3,13],
[2,'river','Thin Ice at Thirty Mile','Perrault repeatedly breaks through river ice while the team searches for a passable route.','thirty-mile',{buck:'Hauls hard from firmer ice whenever the courier plunges into hidden water.',perrault:'Uses fire, rope, and repeated probing to lead the mail across dangerous ice.',francois:'Keeps dogs and traces from piling into the breaks around Perrault.',spitz:'Holds the lead line straight despite cold water and confused footing.'},4,20],
[3,'rebellion','Buck Undermines Spitz','After weeks on trail, Buck protects weaker dogs and quietly challenges Spitz’s punishments.','bennett',{buck:'Intervenes against Spitz while avoiding a premature direct contest.',spitz:'Finds his authority weakening as punishments provoke resistance rather than obedience.',francois:'Recognizes the growing rivalry but cannot settle it with team discipline.',perrault:'Measures progress against the official schedule while tension spreads behind the leader.'},3,30],
[3,'rabbit','The Snowshoe Rabbit Chase','A rabbit breaks across the snow and the camp’s dogs join a moonlit pursuit.','forest',{buck:'Runs at the head of the pursuing mass as the hunt awakens a fierce inherited joy.',spitz:'Cuts across the course to intercept the rabbit and convert the chase into advantage.','sol-leks':'Joins the pack pursuit while keeping clear of the two rivals.','dave':'Leaves his reserve behind in the collective rush after prey.'},4,34],
[3,'fight','Buck Defeats Spitz','The rivals fight with patience and ferocity until Buck breaks Spitz’s legs and the pack closes in.','forest',{buck:'Uses a low feint to break both forelegs and stands as the surviving challenger.',spitz:'Falls after defending himself expertly against Buck’s repeated attacks.','sol-leks':'Waits with the circling dogs until the defeated leader can no longer rise.',dave:'Closes with the pack once the formal contest has ended.'},5,34.2],
[4,'lead','Buck Claims the Lead','François tries Sol-leks in front, but Buck refuses every other place until the men concede.','sled',{buck:'Dodges club and harness until his claim to the lead position is accepted.',francois:'Attempts to preserve routine, then recognizes that only Buck can restore order.',perrault:'Ends the delay by ordering Buck harnessed in the lead.','sol-leks':'Returns willingly to his familiar position once Buck’s claim is settled.'},4,35],
[4,'record','A Record Run to Skaguay','Buck restores discipline and drives the mail team over the route at exceptional speed.','skaguay',{buck:'Reads the trail ahead and enforces steady effort through the entire line.',francois:'Handles the sled behind a team now working at its highest efficiency.',perrault:'Delivers the dispatches ahead of ordinary time and credits the team’s performance.',dave:'Works in contented precision at wheel despite accumulated fatigue.','sol-leks':'Matches Buck’s pace without wasting motion or challenging the new order.'},3,48],
[4,'farewell','Government Couriers Depart','Orders transfer Perrault and François away, ending Buck’s first disciplined partnership.','skaguay',{buck:'Watches the men leave with guarded attachment before accepting a new driver.',perrault:'Hands over a proven lead dog and returns to government courier duties.',francois:'Says farewell to the team whose craft and endurance he helped shape.'},2,49],
[5,'mail','The Heavy Mail Run','Under the Scotch half-breed, the dogs haul mail back toward Dawson through deep snow and short rest.','dawson',{buck:'Pulls from the lead while fatigue settles into muscle and judgment.','scotch-halfbreed':'Maintains a competent routine but cannot reduce the official load or distance.',dave:'Insists on his wheel position even as pain begins to interrupt his work.','sol-leks':'Keeps the traces taut through repetitive days with little recovery.'},3,70],
[5,'dave-fails','Dave Collapses in Harness','Dave repeatedly falls, yet protests removal and struggles back to his place beside the sled.','sled',{buck:'Shortens the team’s pace when Dave’s failing body can no longer answer each command.','scotch-halfbreed':'Examines Dave, removes him reluctantly, and sees that rest gives no relief.',dave:'Crawls back toward the traces because work remains the only identity he accepts.','sol-leks':'Holds his line while the wheel position beside him repeatedly collapses.'},5,73],
[5,'dave-death','The Shot behind the Trees','The driver leaves Dave behind and ends his suffering out of sight of the waiting team.','forest',{buck:'Hears the single shot and understands that Dave will not return to the traces.','scotch-halfbreed':'Carries out the grim mercy privately after every practical remedy fails.',dave:'Dies away from the team after illness makes further work impossible.'},5,74],
[5,'sold','The Team Is Sold','At Skaguay the exhausted dogs are sold to Hal, Charles, and Mercedes for a spring journey.','skaguay',{buck:'Assesses the disordered equipment and inexperienced owners while too depleted to resist.','sol-leks':'Waits in harness-worn silence as the familiar mail routine is dismantled.',hal:'Pays for the team and assumes possession itself proves trail competence.',charles:'Loads household gear without reconciling weight, distance, or dog strength.',mercedes:'Protects clothing and comforts from every proposal to reduce the outfit.'},3,78],
[5,'overload','The Sled Will Not Move','An overloaded sled frozen into the snow resists the team until townspeople force the party to repack.','skaguay',{buck:'Strains once against the immovable load, then stops wasting strength on bad preparation.','sol-leks':'Pulls by habit but cannot shift runners frozen beneath excessive freight.',hal:'Uses the whip instead of checking runners, load, or harness.',charles:'Helps overturn and repack the sled only after public ridicule.',mercedes:'Argues over each discarded possession and restores weight by climbing onto the load.'},4,79],
[5,'starving','Food Runs Out','Misjudged rations, slow travel, and Mercedes’s weight leave people and dogs starving along the thawing trail.','trail',{buck:'Moves only when forced, conserving the last strength in his underfed body.','sol-leks':'Continues from ingrained duty despite ribs, sores, and shrinking rations.',hal:'Cuts portions and increases beating rather than admit the schedule has failed.',charles:'Stumbles through camp tasks with exhaustion replacing his earlier passivity.',mercedes:'Rides amid the failing outfit, grieving loudly while resisting every necessary sacrifice.'},5,95],
[6,'refusal','Buck Refuses the Rotten Ice','At Thornton’s camp, Buck senses danger and remains down while Hal beats him for refusing to start.','east-fork',{buck:'Lies beyond ordinary obedience because instinct and exhaustion both reject the thawing river.',hal:'Escalates from whip to club, determined to make visible submission matter more than safety.',charles:'Waits beside the unstable outfit without challenging Hal’s judgment.',mercedes:'Cries over the violence but still demands that the journey continue.',thornton:'Steps from his camp when punishment becomes likely to kill the dog.'},5,96],
[6,'rescue','Thornton Cuts the Traces','Thornton knocks Hal back, cuts Buck free, and keeps him as the party moves onto the river.','east-fork',{buck:'Collapses beside Thornton with the harness cut away and the beating ended.',thornton:'Places his own body between Buck and the club, accepting a fight to stop the cruelty.',hal:'Retreats with a knife wound to his pride and drives the remaining outfit toward the river.',charles:'Continues after Hal with the weakened dogs and overloaded sled.',mercedes:'Leaves seated on the load, still unable to grasp the immediate danger.'},5,96.1],
[6,'ice','The River Takes the Outfit','From shore, Buck and Thornton see the rotten ice collapse beneath Hal’s party and sled.','east-fork',{buck:'Watches the former owners vanish where his instinct had refused the trail.',thornton:'Reads the breaking surface without surprise and keeps Buck safely ashore.',hal:'Disappears with the sled after forcing the team onto unsafe spring ice.',charles:'Falls through with the collapsing outfit before reaching firm river.',mercedes:'Is carried under with the baggage she had refused to abandon.'},5,96.3],
[6,'recovery','Buck Heals in Thornton’s Camp','Skeet tends Buck’s wounds while Nig offers companionship and Thornton rebuilds his trust.','fire',{buck:'Sleeps deeply, eats safely, and allows affection to replace constant defensive watch.',thornton:'Feeds and handles Buck patiently without demanding proof of obedience.',skeet:'Cleans Buck’s cuts each morning with gentle persistence.',nig:'Greets the recovering dog without rivalry and shares the camp’s easy order.'},2,105],
[6,'burton','Buck Defends Thornton','When Black Burton strikes Thornton in a saloon quarrel, Buck attacks and tears the assailant down.','dawson',{buck:'Launches for Burton’s throat the instant Thornton is struck and cannot be called off until the threat ends.',thornton:'Regains his feet while others pull Buck away from the fallen attacker.','black-burton':'Falls badly injured after turning a dispute into an assault on Thornton.'},5,130],
[6,'rapids','Buck Pulls Thornton from the Rapids','Buck enters dangerous current on a line and lets Hans and Pete haul both him and Thornton to shore.','thirty-mile',{buck:'Swims across the current, reaches Thornton, and holds him while the rope drags them clear.',thornton:'Clings to Buck through the strongest water until the bank crew recovers them.',hans:'Pays out and hauls the rope from shore at the critical angle.',pete:'Braces with Hans and pulls man and dog beyond the rapid.'},5,150],
[6,'wager','The Thousand-Pound Wager','In Dawson, Thornton wagers that Buck can break out and pull a thousand-pound load for one hundred yards.','dawson',{buck:'Waits for Thornton’s private command amid the crowd rather than responding to noise.',thornton:'Stakes his credit and borrowed funds on Buck while fearing what devotion may cost.',hans:'Adds his available money when Thornton’s own funds cannot cover the wager.',pete:'Stands with Thornton beside the marked course and the loaded sled.'},4,170],
[6,'pull','Buck Wins the Wager','Buck breaks the runners free, settles into the load, and pulls it past the measured mark.','dawson',{buck:'Uses controlled surges, then steady traction, to carry the full load across the line.',thornton:'Meets Buck at the finish overwhelmed by relief and affection.',hans:'Witnesses the wager fund become enough to finance a long-planned expedition.',pete:'Helps hold back the crowd as offers for Buck are immediately refused.'},5,170.1],
[7,'lost-mine','The Lost Mine','Thornton, Hans, and Pete travel east, find an old cabin trace, and gather rich gold beside a shallow stream.','east-fork',{buck:'Ranges around the unhurried camp while human work no longer binds him to a daily trail.',thornton:'Washes abundant gold and treats the remote camp as freedom rather than a schedule.',hans:'Builds the working camp and shares the repetitive labour of gathering gold.',pete:'Prospects along the stream and helps store the growing sacks.',skeet:'Keeps close to the human camp during Buck’s longer absences.',nig:'Moves calmly between fire, stream, and the returning Buck.'},3,240],
[7,'wolf','Buck Meets the Timber Wolf','Following a call in the forest, Buck approaches a lone wolf and turns suspicion into play and companionship.','wolf-valley',{buck:'Makes himself small enough to invite play, then runs beside the wolf without surrendering his power.','timber-wolf':'Circles warily before accepting Buck as a companion and leading him deeper into the valley.'},3,248],
[7,'return','Love Draws Buck Back','Buck leaves the wolf and returns to Thornton, though the call continues after the reunion.','fire',{buck:'Presses close to Thornton after choosing the human bond over immediate departure.','thornton':'Welcomes Buck without understanding how far the dog has ranged.',skeet:'Receives Buck back into camp after his unexplained absence.',nig:'Shares the restored camp circle without challenging the return.'},2,249],
[7,'moose','The Great Moose Hunt','Buck isolates an old bull from its herd and follows it for days until he can make the kill.','wolf-valley',{buck:'Controls distance, sleep, and access to water until the wounded bull can no longer resist.'},5,270],
[7,'raid','The Yeehat Attack','Buck returns to find the camp attacked and Thornton, Hans, Pete, and the dogs killed.','east-fork',{buck:'Reads the unfamiliar tracks, finds his companions dead, and turns grief into an immediate charge.',thornton:'Lies dead in the pool after the raid severs Buck’s last governing human bond.',hans:'Dies in the ruined working camp during the attack.',pete:'Dies among the scattered equipment after the raiders overwhelm the camp.',skeet:'Is killed near the human camp she had faithfully shared.',nig:'Is killed in the raid before Buck returns.','yeehat-chief':'Directs the raiding group’s movement through Thornton’s captured camp.'},5,274],
[7,'vengeance','Buck Drives Off the Raiders','Buck attacks the astonished raiders, kills several, and pursues the survivors into the forest.','forest',{buck:'Uses speed, weight, and broken-direction attacks to scatter people who cannot surround him.','yeehat-chief':'Retreats from an animal the raiders interpret through fear and legend.'},5,274.1],
[7,'pack','Buck Joins the Pack','When the wolf pack arrives, Buck survives its challenge and recognizes his former companion.','wolf-valley',{buck:'Answers the pack’s rush, stands unbeaten, and finally runs with them into the valley.','timber-wolf':'Recognizes Buck after the contest and renews their forest companionship.'},4,275],
[7,'ghost-dog','The Ghost Dog Returns','In later seasons Buck leads the pack and revisits the place where Thornton died.','east-fork',{buck:'Returns alone to the abandoned pool, remembers Thornton, and then rejoins the pack’s hunt.'},2,640]
]
